/// <summary>
/// This class is a data contract used for the free-text invoice printing process.
/// </summary>
[DataContract]
class METCBCTFTInvoicePrintingContract
{
    RefRecId custInvoiceTableRecId;

}

Method.Source:
/// <summary>
/// Gets or sets the customer invoice table record ID.
/// </summary>
/// <param name = "_custInvoiceTableRecId">invoice table record ID.</param>
/// <returns>invoice table record ID.</returns>
[DataMember, SysOperationControlVisibility(false)]
public RefRecId parmCustInvoiceTableRecId(RefRecId _custInvoiceTableRecId = custInvoiceTableRecId)
{
    custInvoiceTableRecId = _custInvoiceTableRecId;
    return custInvoiceTableRecId;
}
